import type { TabEvent } from './types';

/*
 * GENERATED DATA — fingered tab for the public-domain classical pieces in
 * hardSongs.ts. Do not edit by hand.
 *
 * Each piece was read note for note from the MIDI file of its Mutopia Project
 * edition (a data file; nothing in it was executed), quantised to 1/24 of
 * a quarter note, and then given a string and fret by a small search that
 * keeps the left hand in one place: every fretted note sounding together fits
 * a 5-fret reach, open strings are preferred, nothing above the 15th fret is
 * used, and no string is asked to sound two notes at once. The fingering is
 * ours; the notes, rhythm and tempo are the edition's. hardSongs.test.ts pins
 * the first bars' pitches so a fingering bug cannot change the music.
 *
 * A row is [start, stringIndex, fret, length]: start and length are in
 * 1/24 of a quarter note (so 24 is one beat), stringIndex 0 is the low E.
 */
export type TabRow = readonly [start: number, stringIndex: number, fret: number, length: number];

export const TAB_UNITS_PER_BEAT = 24;

export function rowsToEvents(rows: readonly TabRow[]): TabEvent[] {
  return rows.map(([start, stringIndex, fret, length]) => ({
    stringIndex,
    fret,
    beat: start / TAB_UNITS_PER_BEAT,
    duration: length / TAB_UNITS_PER_BEAT,
  }));
}

